import{_ as o,o as t,c as r,a6 as n}from"./chunks/framework.BHBQfcoO.js";const g=JSON.parse('{"title":"Routing Engine (RouterCore)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/msd/routing.md","filePath":"architecture/msd/routing.md"}'),a={name:"architecture/msd/routing.md"};function i(s,e,d,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="routing-engine-routercore" tabindex="-1">Routing Engine (RouterCore) <a class="header-anchor" href="#routing-engine-routercore" aria-label="Permalink to &quot;Routing Engine (RouterCore)&quot;">​</a></h1><p><code>src/msd/routing/RouterCore.js</code> is the pathfinding engine behind every MSD line: one instance per MSD card, shared by all line overlays on that card. It decides each line&#39;s viewBox-space geometry: where it bends, how it avoids obstacles, and how multiple lines coordinate into bundles (&quot;cable raceway&quot; behavior).</p><p>User-facing behavior and configuration: <a href="./../../cards/msd/routing.html">Line Routing &amp; Channels</a>. This page covers the internals.</p><p>RouterCore has <strong>zero DOM dependencies</strong>: it&#39;s pure geometry and graph search, which is what makes it unit-testable: <code>tests/routing/*.test.js</code> (<code>npm run test:routing</code>, Node&#39;s built-in test runner) exercises it directly through a small harness (<code>tests/routing/helpers/router-harness.js</code>).</p><hr><h2 id="request-lifecycle" tabindex="-1">Request Lifecycle <a class="header-anchor" href="#request-lifecycle" aria-label="Permalink to &quot;Request Lifecycle&quot;">​</a></h2><ol start="0"><li><code>buildRouteRequest</code> resolves the line&#39;s mode: explicit <code>route:</code> wins, then a card-wide <code>default_mode</code> (if set to something other than <code>auto</code>), otherwise <code>auto</code> resolves straight to <code>smart</code>, unconditionally, not gated on obstacles/channels being present. <code>manhattan</code> and <code>grid</code> are the explicit, always-honored opt-outs for the cheap/non-participating and no-refinement-pass alternatives respectively.</li><li><code>AdvancedRenderer.render()</code> positions control overlays, waits for their DOM to settle, then resolves every overlay&#39;s anchor/attachment points.</li><li><strong>Discovery loop</strong> (<code>AdvancedRenderer._discoverLineRoutes</code>): before anything renders, every line is routed (iterated in a <strong>fixed order sorted by overlay id, not YAML order</strong>) repeatedly, until a full sweep causes zero registry mutations (capped by <code>trunk_discovery_max_passes</code>, default <code>4</code>), which is what makes bundling outcomes independent of declaration order. The loop must use the same <em>complete</em> anchor set (static + attachment-manager virtual anchors) the render pass uses, or control-anchored lines silently fail to resolve and the loop no-ops.</li><li><strong>Render pass</strong> (declaration order, for SVG z-ordering): each <code>LineOverlay.render()</code> calls <code>RouterCore.buildRouteRequest()</code> + <code>computePath()</code>; all cache hits once the loop has converged.</li><li><code>computePath</code> dispatches on mode: <code>manual</code> / <code>direct</code> / corridor-chained (<code>_computeCorridorRouted</code>) / plain A* (<code>_computeGrid</code>, plus <code>_refineSmart</code> for <code>smart</code>).</li><li>After geometry is final (post corner-rounding, pre smoothing), the line&#39;s straight runs are <strong>registered</strong> into the shared registries, making its geometry visible to other lines&#39; future routing decisions.</li></ol><h2 id="core-data-structures" tabindex="-1">Core Data Structures <a class="header-anchor" href="#core-data-structures" aria-label="Permalink to &quot;Core Data Structures&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Structure</th><th>Contents</th><th>Purpose</th></tr></thead><tbody><tr><td><code>_trunks</code></td><td>Trunk rows: bounds, <code>direction</code>, <code>origin</code> (<code>channel</code>/<code>discovered</code>), <code>sourceLineId</code> (creator), <code>crossCenter</code>, <code>members: Map&lt;lineId, [...]&gt;</code> (per-member flow span + derived lane/side metadata, see <a href="#lane-assignment-derived-never-stored">Lane Assignment</a>)</td><td>Bundling. Config channels are pre-seeded rows; discovered rows are created from lines&#39; own straight runs (≥ <code>trunk_min_length</code>, default <code>60</code>)</td></tr><tr><td><code>_crossings</code></td><td>Per-line straight-run records (≥ <code>crossing_min_length</code>, default <code>12</code>)</td><td>Crossing avoidance occupancy</td></tr><tr><td><code>_registryVersion</code></td><td>Counter bumped <strong>only on real registry mutations</strong></td><td>Folded into the route cache key: the mechanism that makes the discovery loop converge and steady state free</td></tr><tr><td><code>_cache</code></td><td>LRU route cache keyed on every request field + <code>_registryVersion</code> + viewBox + obstacle version</td><td>A line recomputes exactly when something it depends on changed</td></tr></tbody></table><h2 id="a-and-cost-biases" tabindex="-1">A* and Cost Biases <a class="header-anchor" href="#a-and-cost-biases" aria-label="Permalink to &quot;A* and Cost Biases&quot;">​</a></h2><p><code>_computeGrid</code> runs 4-direction A* over a coarse grid (<code>grid_resolution</code>) with a turn penalty, plus three per-cell bias layers looked up during the search. When <code>grid_resolution</code> isn&#39;t set in config, <code>_defaultGridResolution()</code> derives it from the viewBox&#39;s own shorter dimension (~1/12th of it, clamped to <code>[16, 64]</code>), since a flat default is only ever right by coincidence for how large the author&#39;s <code>view_box</code> happens to be; it&#39;s recomputed on every call rather than cached, so it stays correct across <code>setViewBox()</code>. Explicit config always wins; values ≤ 4 are silently coerced to <code>32</code>.</p><ul><li><strong>Channel bias</strong> (<code>_buildChannelCostGrid</code>): discount for moving <em>along</em> a prefer channel&#39;s flow direction; penalty inside avoid channels. A prefer discount can break the Manhattan heuristic&#39;s admissibility, so those searches fall back to h=0 (Dijkstra).</li><li><strong>Crossing penalty</strong> (<code>_buildCrossingCostGrid</code>): penalizes moving <em>orthogonally</em> through another line&#39;s registered segment, always non-negative (no admissibility concerns). <strong>Bundle-mates are exempt</strong> (lines sharing a trunk, and the occupants of a corridor being joined) because reaching an outer lane legitimately crosses inner lanes, and penalizing that made A* sneak around segment endpoints instead.</li><li>Cardinal <code>anchor_side</code>/<code>attach_side</code> guarantees are enforced <em>structurally</em> with fixed stub segments spliced around the search (<code>_applyCardinalStubs</code>), not as costs; see below for how long that stub is allowed to be.</li></ul><h2 id="corner-radius-driven-stub-length" tabindex="-1">Corner-Radius-Driven Stub Length <a class="header-anchor" href="#corner-radius-driven-stub-length" aria-label="Permalink to &quot;Corner-Radius-Driven Stub Length&quot;">​</a></h2><p><code>_applyCardinalStubs</code> and <code>_computeManhattan</code>&#39;s own fallback stub logic both splice a <strong>fixed, unsearched</strong> lead-out/lead-in segment onto the true endpoint before any A*/crossing-cost evaluation runs; the pathfinder only searches between the <em>stub</em> endpoints. That reserved length can never be routed around anything, including another line&#39;s already-registered crossing segment; corner geometry takes structural precedence over crossing avoidance, not a cost tradeoff a bias knob can influence.</p><p>Two functions compute it:</p><ul><li><code>stubLengthFor(req)</code>: <code>max(MIN_STUB_LENGTH, cornerRadius*2)</code>, gated on <code>cornerStyle</code> actually rendering an arc/chamfer (<code>round</code>/<code>bevel</code>; a <code>miter</code> line has nothing to make room for). Used unconditionally by <code>_pushBundledApproachLegs</code>&#39;s bundled-corridor lane-nudge distance, since that leg is independently pathfound through the crossing-cost grid, so it isn&#39;t a blind splice.</li><li><code>cardinalStubLengthFor(req, minAutoLength)</code>: used only by the two genuinely blind call sites (<code>_applyCardinalStubs</code>, <code>_computeManhattan</code>&#39;s fallback). An explicit per-line <code>stub_length</code> override (<code>req.stubLength</code>, see below) wins unconditionally if set. Otherwise it returns <code>stubLengthFor(req)</code> when <code>cornerRadiusMode === &#39;forced&#39;</code> (opt-in); by default (<code>&#39;auto&#39;</code>) it returns <code>minAutoLength</code> (the router&#39;s own resolved <code>grid_resolution</code>), leaving the full route shape to the crossing-aware search. Rendered corner radius still targets the configured value wherever the chosen path&#39;s leg lengths allow it.</li></ul><p><code>cornerRadiusMode</code> is a per-request field resolved in <code>buildRouteRequest</code> and folded into <code>_cacheKey</code> (<code>CRM:</code>) alongside <code>cornerRadius</code>/<code>cornerStyle</code>. A per-line <code>stub_length</code> (viewBox units) bypasses both <code>auto</code>/<code>forced</code> computations entirely, for a line that needs a specifically shorter or longer lead-out without touching the card-wide <code>grid_resolution</code>.</p><p><strong>Stroke-width-aware corner clearance</strong>: <code>buildRouteRequest</code> resolves <code>req.width</code> from the line&#39;s style (<code>style.width</code>/<code>style.stroke_width</code>, default <code>2</code>) and threads it into each registered <code>_crossings</code> entry. <code>_distanceToNearestOtherLineSegment</code> nets <code>(askingWidth + otherWidth) / 2</code> off the raw centerline-to-centerline distance before <code>_applyCornerRounding</code> clamps a corner&#39;s radius to it; two thick parallel lines get a smaller effective radius at the same lane spacing than two thin ones, correctly accounting for rendered edges rather than centerlines. <code>width</code> participates in the registration change-diff, so a width-only edit still bumps <code>_registryVersion</code>.</p><h3 id="corner-room-refinement-corner-room-weight" tabindex="-1">Corner-Room Refinement (<code>corner_room_weight</code>) <a class="header-anchor" href="#corner-room-refinement-corner-room-weight" aria-label="Permalink to &quot;Corner-Room Refinement (`corner_room_weight`)&quot;">​</a></h3><p>On by default (<code>DEFAULT_CORNER_ROOM_WEIGHT = 4</code>); a different tool from the stub reservation above, which is a <em>blind, structural</em> reservation; <code>corner_room_weight</code> does a <em>cost-compared</em> local refinement for <strong>interior</strong> corners the stub mechanism never reaches, reusing <code>_refineSmart</code>&#39;s elbow-nudge search (gated on <code>smart_proximity &gt; 0</code> OR <code>cornerRoomWeight &gt; 0 &amp;&amp; cornerStyle === &#39;round&#39; &amp;&amp; cornerRadius &gt; 0</code>). <code>_estimateCornerRadii</code> (shared with <code>_applyCornerRounding</code>&#39;s pre-calc) gives refinement scoring and final rendering one source of truth for &quot;how would this corner round.&quot; Each elbow-shift candidate&#39;s cost gets <code>+ shortfall * cornerRoomWeight</code> added, <code>shortfall</code> being the sum of <code>max(0, cornerRadius - achievedRadius)</code> across the candidate&#39;s corners, compared against the same computation on the unmodified baseline.</p><p>Candidate generation produces only the 2 geometrically-meaningful shift directions per elbow (the other 2 always degenerate to a no-op once compacted), each a 2-point replacement so both adjacent legs stay orthogonal by construction, legitimately adding one bend, capped by <code>smart_max_extra_bends</code> (default <code>3</code>). A candidate is rejected outright (never repaired) if its path crosses an obstacle, reverses direction along an axis, or would land outside the card&#39;s <code>viewBox</code> (<code>tests/routing/refine-smart-viewbox-bounds.test.js</code>).</p><h2 id="per-waypoint-corner-radius-override" tabindex="-1">Per-Waypoint Corner Radius Override <a class="header-anchor" href="#per-waypoint-corner-radius-override" aria-label="Permalink to &quot;Per-Waypoint Corner Radius Override&quot;">​</a></h2><p><code>manual</code>-routed lines can override an individual corner&#39;s rounding radius (<code>round</code>) or chamfer size (<code>bevel</code>) via a 3rd number on a coordinate waypoint (<code>[x, y, radius]</code>), instead of every corner sharing the line&#39;s single <code>req.cornerRadius</code>. This is a target substitution: <code>_estimateCornerRadii</code> already computes a per-corner radius internally (room clamp, neighbor-clearance shrink, consecutive-corner scaling) from one global scalar; a per-waypoint override replaces which value each corner&#39;s clamp chain starts from, via a <code>perCornerRadius</code> option (<code>null</code> = inherit <code>radiusGlobal</code>); everything downstream still applies as a ceiling over whichever target is in effect. <code>_applyCornerBeveling</code> does <strong>not</strong> share <code>_estimateCornerRadii</code> and carries the identical substitution independently.</p><p>A waypoint&#39;s radius travels <em>with</em> its point through <code>_computeManual</code>&#39;s pipeline (as <code>{pt, radius}</code> entries, deduped on <code>pt</code>) rather than being re-derived by index, since <code>_computeManual</code> can drop or dedup a waypoint and misalign a naive index mapping. Named-anchor waypoints always resolve to <code>radius: null</code>. Scoped to <code>manual</code> mode only; every other mode passes <code>null</code> into <code>_applyCornerRounding</code>/<code>_applyCornerBeveling</code>.</p><p><code>_cacheKey</code> folds <code>JSON.stringify(req.waypoints)</code> into the key (empty string for non-manual lines), so a per-corner radius edit with unchanged endpoints can&#39;t hit a stale cache entry. <code>invalidate(id)</code>&#39;s scan matches keys via <code>k.startsWith(</code>${id}@<code>)</code>.</p><h2 id="channel-entry-is-always-at-an-end" tabindex="-1">Channel Entry Is Always At An End <a class="header-anchor" href="#channel-entry-is-always-at-an-end" aria-label="Permalink to &quot;Channel Entry Is Always At An End&quot;">​</a></h2><p><code>_channelCrossingPoints</code> always clamps <code>entryFlow = Math.max(lo, Math.min(hi, approachFlow))</code> to the channel&#39;s own flow-axis bounds <code>[lo, hi]</code>; whenever the approach point sits outside that range, it snaps to the nearest of the channel&#39;s two ends. There is no code path that lets a line join a channel&#39;s centerline mid-span from the side; every crossing is an end-to-end (or end-to-partway-through) traversal by construction. This is an architectural constraint, not a gap; genuine mid-span side-entry would be a substantial design change.</p><h2 id="post-search-reshape-orthogonality-invariant" tabindex="-1">Post-Search Reshape: Orthogonality Invariant <a class="header-anchor" href="#post-search-reshape-orthogonality-invariant" aria-label="Permalink to &quot;Post-Search Reshape: Orthogonality Invariant&quot;">​</a></h2><p>After <code>_computeGrid</code>&#39;s A* search reconstructs a path, a final reshape pass snaps the first and last segments onto the exact requested endpoint coordinates (the search itself only ever lands on grid-quantized points). Each side has a <strong>degenerate-axis relief</strong>: when the <em>required</em> axis for that end has zero real distance to cover (e.g. a <code>channel_axis</code> hint wants vertical, but start/end already share the same y), forcing the segment onto that axis anyway would insert a spurious zero-length elbow, so the relief accepts the reconstructed segment as-is, but only once it has confirmed the segment is actually orthogonal (<code>actuallyHorizontal || actuallyVertical</code>), since under some grid-snap geometries the raw reconstructed segment can be diagonal, which this Manhattan-only router can&#39;t render or corner-round.</p><p>This invariant (<strong>every segment <code>_computeGrid</code> produces must be axis-aligned</strong>) is asserted in <code>tests/routing/diagonal-segment.test.js</code>. Separately, <code>meta.bends</code>/<code>meta.segments</code> (and <code>_costComposite</code>&#39;s own bend count) are derived from <code>_compactPolyline(pts).length</code>, never raw <code>pts.length</code>; a collinear &quot;phantom&quot; point (typically a stub&#39;s landing point continuing the same direction) otherwise over-counts by one; <code>_compactPolyline</code> still preserves genuine same-axis reversal points (see Convergence Discipline below).</p><p><strong>Same-grid-cell collapse</strong>: a leg whose raw <code>req.a</code>/<code>req.b</code> round to the same grid cell (e.g. a corridor hop shorter than one <code>grid_resolution</code>) makes the A* search &quot;arrive&quot; on its first pop, producing one degenerate point that an existing guard duplicates before the reshape snaps both copies back onto the two real endpoint coordinates. The reshape&#39;s hard-hint branches test the current, post-snap segment directly for this case, since the grid&#39;s pre-snap point is just the collapsed cell&#39;s own center. The generic branch (no hard hint) uses a narrower test gated on <code>wasSameCellCollapse</code>, captured at the same point the guard duplicates the collapsed point, so only the collapsed case gets this treatment, and the normal case still uses the original pre-snap comparison, which would false-positive if applied unconditionally. Covered by <code>tests/routing/same-cell-collapse-diagonal.test.js</code>.</p><h2 id="corridor-crossing-direction-enforcement" tabindex="-1">Corridor-Crossing Direction Enforcement <a class="header-anchor" href="#corridor-crossing-direction-enforcement" aria-label="Permalink to &quot;Corridor-Crossing Direction Enforcement&quot;">​</a></h2><p>A <code>channel_axis</code>-sourced hint&#39;s hard block in <code>_computeGrid</code>&#39;s neighbor-expansion loop guarantees a leg&#39;s departure from (or arrival at) a corridor crossing lands on the <em>required axis</em>. This is extended, on both sides, to also reject the exact reverse of <code>continuationDir</code> when known (<code>req._continuationDirFirst</code>/<code>Last</code>, from <code>_computeCorridorRouted</code>&#39;s <code>entryHint</code>/<code>departHint</code>); an axis-only check permits arrival from either direction along that axis, including a same-axis reversal against the corridor&#39;s own established flow, which the direction check closes. Covered by <code>tests/routing/channel-entry-direction.test.js</code>.</p><p><code>_computeCorridorRouted</code>&#39;s chain loop tracks <code>prevChannelDir</code> (the last known real direction of travel) so a leg departing a channel whose own entry→exit crossing is <em>degenerate</em> (zero real distance, <code>entry === exit</code>) still gets a &quot;don&#39;t reverse&quot; guarantee carried from an earlier channel in the chain. When the chain&#39;s very <em>first</em> channel is itself the degenerate one, there&#39;s no earlier channel to carry a direction from; the fallback derives one from the approach leg&#39;s own real displacement (<code>cursor</code> before this channel&#39;s reassignment, to <code>entry</code>) instead of leaving <code>prevChannelDir</code> at <code>0</code>. Covered by <code>tests/routing/channel-chain-first-hop-degenerate.test.js</code>.</p><p>Note: <code>_buildChannelCostGrid</code>&#39;s per-cell &#39;prefer&#39; discount applies to any leg carrying the channel in <code>req.channels</code>, not just the leg designated as the official crossing; an approach leg still technically outside the channel earns the same reward as the real crossing leg. Known architectural characteristic, not narrowed by the direction fix above; see below for the case where it required its own fix.</p><h2 id="plain-candidate-channel-bias-leak" tabindex="-1">Plain-Candidate Channel-Bias Leak <a class="header-anchor" href="#plain-candidate-channel-bias-leak" aria-label="Permalink to &quot;Plain-Candidate Channel-Bias Leak&quot;">​</a></h2><p><code>computePath</code>&#39;s prefer-channel/discovered-trunk branch compares a <code>plain</code> candidate (the honest, no-corridor route) against every corridor option on <code>effectiveCost</code> (<code>meta.cost</code> + a crossing-avoidance tiebreaker). <code>computePlain()</code> builds its own request: any channel id present in <code>explicitCorridors</code> (a <code>force</code>/<code>prefer</code> channel this line could chain through) is stripped from <code>req.channels</code> before it reaches <code>_computeGrid</code>/<code>_refineSmart</code>, so the comparison baseline is honestly &quot;what if this line never used the channel at all&quot;; otherwise <code>plain</code> would receive the same channel-bias discount (per the leak noted above) while never using the corridor mechanism, unreliable once bend cost is cheap relative to the discount (e.g. a low <code>turn_penalty</code>). <code>avoid</code>-mode channel ids stay in place, since their repulsion bias is exactly what an honest plain route should still respect. The corridor can still legitimately win the comparison outright when no competing line creates a crossing risk: a deliberate, cost-vetted use, not a leak. Covered by <code>tests/routing/channel-plain-candidate-bias.test.js</code>.</p><h2 id="trunk-and-branch-bundling" tabindex="-1">Trunk-and-Branch (Bundling) <a class="header-anchor" href="#trunk-and-branch-bundling" aria-label="Permalink to &quot;Trunk-and-Branch (Bundling)&quot;">​</a></h2><p>A channel is just a <strong>pre-seeded trunk</strong>; a discovered trunk is a corridor learned from another line&#39;s routed path. Both live in <code>_trunks</code> and flow through the same corridor-composition machinery:</p><ul><li><strong>Discovery</strong> (<code>_discoverTrunkCandidates</code>): a line finds joinable trunks by flow-axis overlap (≥ <code>trunk_min_overlap</code>, default <code>60</code>) and cross-axis proximity (≤ <code>trunk_proximity</code>, default <code>32</code>, a hard cutoff; see Known Limitations). Exclusions: corridors already referenced explicitly, trunks the line itself <em>created</em>, ghost shells with zero members, and rows authored with <code>discoverable: false</code>. Membership is deliberately <strong>not</strong> an exclusion; a joined line must be able to re-discover its own trunk on recompute, or joining would silently revert (&quot;join ratchet&quot;). Discovery runs regardless of a line&#39;s <code>route_channels</code>, which only controls whether a channel is <em>mandatory</em>/cost-biased for lines listing it; <code>discoverable: false</code> is the only way to scope a channel to just those users.</li><li><strong>Composition</strong> (<code>_computeCorridorRouted</code>): approach leg → through leg → depart leg per corridor, each independently pathfound. A discovered trunk (or prefer channel) chain is an <em>optional candidate</em> compared against the plain route by real cost; only <code>force</code> channels are mandatory and skip trunk discovery entirely. <code>_polylineSelfIntersects</code> hard-rejects (never repairs) a chain whose own non-adjacent legs cross, gated <code>!hasForceChannel</code>; a large enough channel discount can otherwise make a self-crossing candidate look cheapest, since the crossing-cost term only ever checks a candidate against <em>other lines&#39;</em> segments, never its own earlier legs. Covered by <code>tests/routing/corridor-self-crossing.test.js</code>.</li><li><strong>Discount cap</strong> (<code>_trunkBundleDiscountCap</code>, config <code>trunk_bundle_discount_cap</code>, default <code>150</code>): <code>_corridorDelta</code>&#39;s <code>prefer</code>-mode discount credits at most this much distance toward a <em>discovered</em> trunk&#39;s cost reduction (a <code>force</code>/<code>prefer</code> channel authored via <code>route_channels</code> is never capped). A real, binding tuning value: it stops a line whose own plain route is already short and clean from detouring into an unrelated discovered trunk purely to farm the discount.</li><li><strong>Registration</strong> (<code>_registerLineSegments</code> → <code>_mergeOrRegisterTrunk</code>): a finished route&#39;s straight runs merge into geometrically-matching trunk rows as member spans, or create new rows. Registration is <strong>diff-in-place</strong>: matching entries update with no reported change on identical geometry, and only entries the scan didn&#39;t touch are dropped. Rows are never deleted; emptied &quot;shell&quot; rows reactivate on rejoin.</li></ul><h2 id="lane-assignment-derived-never-stored" tabindex="-1">Lane Assignment: Derived, Never Stored <a class="header-anchor" href="#lane-assignment-derived-never-stored" aria-label="Permalink to &quot;Lane Assignment: Derived, Never Stored&quot;">​</a></h2><p><code>_trunkLaneAssignment(corridor, lineId, chainSideHint)</code> computes <code>{laneIndex, laneCount, offset}</code> as a <strong>pure function of the trunk&#39;s current member set</strong> on every call; there is deliberately <strong>no stored lane state</strong>. The predecessor (<code>_channelLineIndex</code>, a permanent insertion-order map) caused the engine&#39;s recurring failure class: stateful per-corridor bookkeeping the discovery loop couldn&#39;t converge over. Membership changes bump <code>_registryVersion</code>; identical re-registration is a strict no-op.</p><ul><li><strong>Discovered trunk</strong>: the creator (<code>sourceLineId</code>) implicitly holds lane 0 at offset 0; its path <em>is</em> the centerline (<code>crossCenter</code>). Joiners (members minus creator, plus the asking line, sorted lexicographically within each side) alternate sides: <code>+s, -s, +2s, -2s, …</code>. The row&#39;s cross-axis band width is derived from joiner count (<code>_trunkBandHalfWidth</code>), grown symmetrically so the band center never drifts. The creator&#39;s own natural side is recorded per-member and, when strictly positive, flips which side-group gets the lower <code>laneIndex</code>, a lane <em>numbering</em> preference only, since lane bookkeeping runs after routing, not before.</li><li><strong>Config channel</strong>: all users get centered offsets <code>(i − (n−1)/2) × line_spacing</code>, clamped to the authored band. Ordering among members uses the same <code>naturalSide</code>-first, lineId-tie-break sort the discovered branch uses; a pure-lexicographic sort by id alone can order lanes exactly backwards from each line&#39;s own geometry, creating unnecessary crossovers. Covered by <code>tests/routing/channel-lane-natural-side.test.js</code>.</li><li><strong>Chain-aware ordering</strong>: both branches route the same-side tie-break through shared <code>_sameSideOrder</code>/<code>_bothGroundedAt</code> helpers rather than maintaining independent copies; see <a href="#chain-aware-corridor-lane-consistency">Chain-Aware Corridor Lane Consistency</a> below.</li></ul><h2 id="matched-sibling-corner-arc-clearance" tabindex="-1">Matched-Sibling Corner-Arc Clearance <a class="header-anchor" href="#matched-sibling-corner-arc-clearance" aria-label="Permalink to &quot;Matched-Sibling Corner-Arc Clearance&quot;">​</a></h2><p>When two lines sharing a trunk/channel row turn the identical way at corresponding ends of the shared corridor (a &quot;bundle-mate&quot; match), their rendered corner arcs are cleared against each other&#39;s <em>exact</em> geometry, not just their straight runs; <code>trimLo</code>/<code>trimHi</code> (inside <code>_distanceToNearestOtherLineSegment</code>) already handles a neighbor&#39;s straight, still-sharp span; this covers the neighbor&#39;s own <strong>curved</strong> region, which a linear trim can&#39;t represent.</p><ul><li><strong>Identification</strong> (<code>_matchedTrunkCorner</code>, <code>_matchedSiblingArcs</code>): a corner is a trunk-exit corner when its incoming run&#39;s flow span exactly matches this line&#39;s own registered member entry in some <code>_trunks</code> row. A sibling &quot;matches&quot; when it&#39;s a member of that row with a corner at the same relative end and an <strong>identical <code>(vInUnit, vOutUnit)</code> pair</strong> (not just the same <code>offsetDir</code>) since two geometrically distinct turns can share an <code>offsetDir</code> while sweeping in opposite rotational senses.</li><li><strong>Exact clearance</strong> (<code>_siblingArcClearance</code>): once a sibling&#39;s corner is resolved, its full swept arc is sampled at K+1 angles (K=12) against the candidate&#39;s own arc, taking the true minimum pairwise distance (verified against <code>tests/routing</code>&#39;s <code>flattenSvgPath</code> oracle to within ~0.5%); matched single-index sampling isn&#39;t sufficient, since the true closest-approach pair between two differently-centered arcs generally sits at different sweep fractions on each.</li><li><strong>Combining with the existing proxy</strong>: the exact signal only ever <strong>floors up</strong> (<code>Math.max</code>) the existing <code>_distanceToNearestOtherLineSegment</code> proxy, which still runs unmodified against every line including matched siblings; never excludes or replaces it. Excluding a matched sibling from the proxy and relying solely on the exact check causes genuine oscillation (two mutually-matched siblings each reading the other&#39;s previous-pass radius with no monotonic anchor); flooring against the untouched, monotonic proxy guarantees a fixed point.</li><li><strong>Convergence cost</strong>: can add up to one extra discovery-loop pass versus not having it, safely within the existing pass cap in every tested scenario.</li></ul><p>Covered by <code>tests/routing/matched-corner-arc-clearance.test.js</code>.</p><h2 id="corridor-entry-nudging" tabindex="-1">Corridor-Entry Nudging <a class="header-anchor" href="#corridor-entry-nudging" aria-label="Permalink to &quot;Corridor-Entry Nudging&quot;">​</a></h2><p>Bundle members approach a shared corridor via <code>_pushBundledApproachLegs</code>, which builds the <code>from → nudge → mid → to</code> leg split used both by <code>_channelCrossingPoints</code>&#39;s entry taper and by ordinary bundled-approach legs. Several details govern where <code>nudge</code>/<code>mid</code> land:</p><ul><li><strong>Grace-zone taper</strong>: <code>_channelCrossingPoints</code> reserves <code>min(stubLengthFor(stubReq), halfSpan)</code> units of flow-axis room ahead of a channel entry whenever <code>laneCount &gt; 1</code>, so a real cross-axis lane correction has room to render instead of a zero-length kink. <code>entryAlreadyInside</code> (whether the boundary is fundamentally a cross-axis-only correction, so the leg&#39;s arrival hint stays a soft &quot;don&#39;t reverse&quot; guarantee rather than a hard axis-lock) is captured <em>before</em> the taper moves <code>entryFlow</code>, not re-derived afterward; re-deriving it post-move would always read <code>false</code> and wrongly escalate the hint to a geometrically unsatisfiable hard lock.</li><li><strong>Grid-quantization alias guard</strong>: two quantization functions run over the same grid (<code>Math.floor</code> for a registered segment&#39;s cell vs. <code>Math.round</code> for the A* query side) which can disagree at a cell boundary and alias two genuinely-distinct rows into one cell, triggering a false parallel-overlap penalty against an unrelated line. <code>_taperAliasesRegisteredSegment</code> checks every registered segment for this alias before a candidate coordinate is committed (taper or <code>corridorOffset</code> alike); on a hit, the taper is skipped or <code>corridorOffset</code> falls back to <code>0</code>, since both are purely cosmetic and a tighter fallback corner is always safe. A structurally cross-axis-only leg has its hint downgraded from a hard <code>channel_axis</code> lock to a softer hint, mirroring <code>entryAlreadyInside</code>&#39;s own downgrade. Covered by <code>tests/routing/channel-taper-grid-alias.test.js</code>.</li><li><strong>Conflict-extension search</strong>: <code>corridorOffset</code> (<code>stubLengthFor(stubReq) + laneIndex * lineSpacing</code>) has no inherent awareness of <em>other</em> lines&#39; still-active approach segments; the smallest-<code>laneIndex</code> member&#39;s nudge can land within another member&#39;s not-yet-turned approach run, producing a real crossing. If the resulting <code>(nudge, mid)</code> leg runs unsafely close to another registered segment (<code>_pureCrossAxisLegTooCloseToOtherLine</code>), the offset is extended in <code>lineSpacing</code>-sized steps (up to the <code>available</code> clamp), taking the smallest safe extension; when none exists, <code>corridorOffset</code> is left as computed and the pre-existing detour mechanism still applies. Covered by <code>tests/routing/kelvin-bundle-crossing.test.js</code>.</li><li><strong>Cross-axis-aware sizing</strong>: the entry&#39;s two lane-separation-jog corners are constrained by the <strong>cross-axis</strong> lane-offset distance (<code>line_spacing</code>-driven, typically 8-12px), not <code>corner_radius</code>. The <code>corner_radius</code> used to size <code>rawOffset</code> is capped at <code>min(corner_radius, crossDist * 0.325)</code> (<code>0.325</code> from the <code>0.65</code> consecutive-corner fill-fraction split), but only when it doesn&#39;t change whether the reservation saturates against <code>available</code>; a corridor <em>exit</em> leg relies on the larger, uncapped reservation overshooting <code>available</code> so <code>mid</code> coincides with <code>to</code> (<code>midIsTo</code>), collapsing a 3-leg structure into one clean corner. Covered by <code>tests/routing/kelvin-bundle-crossing.test.js</code> and <code>tests/routing/channel-chain-transition-taper.test.js</code>.</li></ul><h2 id="bundle-entry-corner-geometry" tabindex="-1">Bundle-Entry Corner Geometry <a class="header-anchor" href="#bundle-entry-corner-geometry" aria-label="Permalink to &quot;Bundle-Entry Corner Geometry&quot;">​</a></h2><p>A bundle member&#39;s lane-separation jog, rendered as a plain 90°-quarter-circle fillet, is capped at roughly <code>crossDist * 0.325</code> independent of <code>corner_radius</code>. Since <code>crossDist</code> differs per member, entry curves render at visibly different, undersized radii even with an identical configured <code>corner_radius</code>, unlike a later channel-to-channel transition, where every member has generous leg room and renders uniformly at full radius. No config knob touches <code>crossDist</code> itself, and clamping every member to the group&#39;s smallest achievable radius is uniform but wrong; the goal is each member as close to its <em>requested</em> radius as possible.</p><p><strong>Reverse curve</strong>: <code>reverseCurveGeometry</code> (module-level pure function) computes a road/rail S-curve lane-change: two tangent circular arcs of shared radius <code>R</code> connecting a flow-axis-aligned line to a parallel one offset by <code>d</code> (<code>crossDist</code>) on the cross axis. Identities: <code>d = 2R(1-cosθ)</code>, <code>L = 2R sinθ</code>, <code>θ</code> capped at 90°. A small <code>crossDist</code> sweeps a smaller portion (<code>θ</code>) of the same target radius rather than needing a smaller circle, so every member independently targets and achieves <code>radiusGlobal</code> given enough room; when <code>d &gt; 2R</code> the excess becomes a plain straight segment, and when the target radius doesn&#39;t fit the room, <code>R</code> is re-derived from the room constraint (<code>θ = 2·arctan(d / (2·Lavail))</code>, <code>R = Lavail / sinθ</code>), degrading gracefully toward a hard corner. Bundle-entry legs skip the crossDist-based shrink above and keep the full <code>2 × corner_radius</code> reservation, since the reverse curve can use the extra room; exit legs are unaffected. <code>_pushBundledApproachLegs</code> records each entry hint; <code>_buildBundleEntryReverseCurves</code> matches hints back onto the final point list by coordinate and stores a <code>.reverseCurve</code> descriptor consumed by a dedicated rendering branch. Shipped as the default, no config knob. Covered by <code>tests/routing/bundle-entry-radius-coordination.test.js</code> and pinned assertions in <code>tests/routing/kelvin-bundle-crossing.test.js</code> / <code>tests/routing/entry-taper-grace-zone.test.js</code>.</p><p><strong>Concentric positioning</strong>: <code>corridorOffset</code> unconditionally adds <code>laneIndex * lineSpacing</code> to every member&#39;s nudge distance, staggering entries apart even when nothing requires it (the term exists for a real case elsewhere: vertically-stacked, same-<code>anchor_side</code> controls whose stubs would otherwise run coincident before diverging late). Since the conflict-extension search above already re-derives however much separation a line needs on demand, bundle-entry legs use <code>laneStagger = bundleEntryHints ? 0 : laneIndex * lineSpacing</code>, starting from a shared, unstaggered baseline; bundle-exit legs keep the original stagger (exit-leg saturation, <code>midIsTo</code>, is sensitive to this term&#39;s magnitude). Members whose jog never reaches a sibling&#39;s approach row land on the identical unstaggered position; members with a longer jog still get pushed out when a real conflict is detected. Covered by <code>tests/routing/bundle-entry-radius-coordination.test.js</code> and a pinned assertion in <code>tests/routing/kelvin-bundle-crossing.test.js</code>.</p><h2 id="chain-aware-corridor-lane-consistency" tabindex="-1">Chain-Aware Corridor Lane Consistency <a class="header-anchor" href="#chain-aware-corridor-lane-consistency" aria-label="Permalink to &quot;Chain-Aware Corridor Lane Consistency&quot;">​</a></h2><p>Lane assignment (<code>_trunkLaneAssignment</code>) decides which side/offset a line gets at a corridor <strong>locally, one corridor at a time</strong>, with no inherent visibility into what the same line (or a sibling sharing that corridor) decides at any <em>other</em> corridor in a multi-corridor chain. Two distinct problems follow: one line&#39;s own side disagreeing with itself across its chain (Phase 1), and two different lines&#39; relative order at one corridor failing to compose with their relative order at another they also share (Phase 2).</p><h3 id="phase-1-chain-self-consistency" tabindex="-1">Phase 1: Chain Self-Consistency <a class="header-anchor" href="#phase-1-chain-self-consistency" aria-label="Permalink to &quot;Phase 1: Chain Self-Consistency&quot;">​</a></h3><p>The full chain of corridors a line will traverse is known up front (<code>chainChannels</code>, built by <code>_mergeCorridors</code>). <code>naturalSide</code>/<code>naturalLean</code>&#39;s sign convention (negative = north/west, positive = south/east) is <strong>frame-fixed</strong> (it doesn&#39;t rotate with direction of travel) so two corridors&#39; &quot;positive&quot; doesn&#39;t mean the same physical side of a bundle unless corrected for how travel direction differs between them. <code>corridorFlowFactor(flowSign, horizontal)</code> computes <code>k = flowSign × (horizontal ? +1 : -1)</code> per corridor per line. Given a line&#39;s real, locally-measured <code>naturalLean</code> at one <strong>canonical</strong> corridor in its chain (<code>_naturalLeanAt</code>), the chain-consistent target at any other corridor <code>B</code> is <code>offsetRel = naturalLean(canonical) × k(canonical)</code>, <code>targetLean(B) = offsetRel × k(B)</code>, <code>targetSide(B) = Math.sign(targetLean(B))</code>. Every <code>k</code> is ±1, so magnitude never propagates (only sign) and the transform is its own inverse. Only a chain&#39;s first-or-last corridor can be a valid canonical anchor; a discovered trunk&#39;s own creator is excluded from having a side at all.</p><p><code>_chainSideAssignment(chainChannels, lineId, rawA, rawB)</code> returns <code>Map&lt;corridorId, {side, lean, offsetRel, k, grounded}&gt; | null</code> (null for a single-corridor chain), computed once per <code>_computeCorridorRoutedAttempt</code> call and threaded as <code>chainSideHint</code> into every <code>_trunkLaneAssignment</code> call the attempt makes; the same values are recorded on <code>meta.chainSides</code> so registration reuses what was just rendered. The member tuple carries <code>[flowLo, flowHi, naturalSide, cornerInfo, naturalLean, offsetRel, k, grounded]</code>; <code>naturalLean</code> stays unmodified; only the discretized <code>naturalSide</code> is overridden when a chain hint applies. <code>grounded</code> (whether this member&#39;s chain canonical anchor is this corridor) feeds Phase 2. Covered by <code>tests/routing/chain-side-propagation.test.js</code> and <code>tests/routing/chain-self-consistency-regression.test.js</code>.</p><h3 id="phase-2-cross-line-consistency" tabindex="-1">Phase 2: Cross-Line Consistency <a class="header-anchor" href="#phase-2-cross-line-consistency" aria-label="Permalink to &quot;Phase 2: Cross-Line Consistency&quot;">​</a></h3><p>Phase 1 makes one line&#39;s own <code>naturalSide</code> chain-consistent; it says nothing about two different lines whose relative order at one shared corridor might not compose with their order at another. The same-side tie-break&#39;s magnitude comparison (<code>Math.abs(leanOf(a)) − Math.abs(leanOf(b))</code>) is where this bites, since neither <code>naturalLean</code> value carries any notion of whether it&#39;s measured in a trustworthy frame at that corridor. The mechanism reuses Phase 1&#39;s discipline (one grounded reference, sign/topology propagated via a closed-form ±1 factor, magnitude never propagated) applied to a <em>pair</em> of lines:</p><ol><li><strong>Groundedness gate</strong> (<code>_bothGroundedAt</code>, <code>_locallyGrounded</code>): a corridor&#39;s recorded <code>naturalLean</code> magnitude is safe to compare between two members only when it&#39;s each member&#39;s own chain canonical anchor (<code>grounded</code>), plus a structural floor: the two lines must also co-occur as members in some other differently-oriented corridor (catches registrations that bypassed <code>_chainSideAssignment</code>, where <code>grounded</code> silently defaults to <code>true</code>). Applied uniformly to both <code>_trunkLaneAssignment</code> branches.</li><li><strong>Seed-and-propagate</strong> (<code>_pairwiseCrossCorridorOrder</code>), when the corridor itself isn&#39;t jointly grounded: among the other co-occurring corridors, a seed is valid only if both lines are locally grounded there (exactly one valid seed required; zero or 2+ falls through to lexicographic). The pair&#39;s order at the seed maps to the target via a binary handedness factor: <code>pairOrderHandedness = sign((kASeed·kATarget) × (kBSeed·kBTarget))</code>, <code>orderAtTarget = orderAtSeed × handedness</code>, composing across any chain length for free since every <code>k</code> is ±1.</li><li><strong>Group-size restriction</strong>: the shared comparator (<code>_sameSideOrder</code>) only attempts <code>_pairwiseCrossCorridorOrder</code> when exactly 2 lines are in the same-side group, since independent pairwise resolutions across 3+ lines have no guarantee of composing into the transitive order <code>Array.prototype.sort</code> requires. 3+-way groups fall back to lexicographic (see Known Limitations).</li></ol><p>Covered by <code>tests/routing/chain-side-propagation.test.js</code>, <code>tests/routing/pairwise-cross-corridor-order.test.js</code>, and <code>tests/routing/chain-self-consistency-regression.test.js</code>.</p><h2 id="convergence-discipline" tabindex="-1">Convergence Discipline <a class="header-anchor" href="#convergence-discipline" aria-label="Permalink to &quot;Convergence Discipline&quot;">​</a></h2><p>The discovery loop only terminates affordably because of three invariants:</p><ol><li><strong>Idempotence</strong>: re-registering identical geometry must not report a change.</li><li><strong>Derived state</strong>: anything computed <em>from</em> the registries (lanes, band widths, lane counts) is recomputed from current state, never incrementally mutated.</li><li><strong>History independence</strong>: <code>setOverlays</code> with a changed overlay set resets the discovered registries. Bundle arrangements can be genuine cost ties with multiple stable outcomes (whichever line routes first picks the winner) so each config&#39;s outcome must be a function of the config plus the fixed loop order, never of edit history.</li></ol><p>The regression suite encodes these directly: the fixed-point test (cache-cleared recompute reproduces the converged answer with zero version bumps) is the canary for the whole class.</p><p><strong>Debug forensics</strong>: each cache entry&#39;s key embeds the <code>_registryVersion</code> it was stored at (<code>…|RV:n</code>), so <code>[...router._cache.keys()]</code> reconstructs the order lines were actually computed in. <code>RouterCore.prototype.trunks()</code> (wired to <code>window.lcards.debug.msd.routing.trunks(cardId)</code>) snapshots every trunk row (id, origin, direction, <code>sourceLineId</code>, bounds, <code>crossCenter</code>, member ids) for inspecting bundling state without reaching into private fields; the MSD Studio dialog&#39;s &quot;Discovered Trunks&quot; overlay reads the same method live. Every <code>computePath</code> result also carries <code>meta.debug: { stubLength, gridResolution, cornerRadiusMode, cornerRadius }</code>: the router&#39;s resolved values for that line.</p><h2 id="pitfalls" tabindex="-1">Pitfalls <a class="header-anchor" href="#pitfalls" aria-label="Permalink to &quot;Pitfalls&quot;">​</a></h2><ul><li><code>grid_resolution</code> values ≤ 4 are silently coerced to 32.</li><li><code>channels</code> config lives at <code>msd.channels</code>, not <code>msd.routing.channels</code> (<code>MsdCardCoordinator</code> assembles RouterCore&#39;s config as <code>{ ...mergedConfig.routing, channels: mergedConfig.channels }</code>).</li><li>Never call <code>computePath</code> with endpoints other than the line&#39;s real resolved anchors &quot;just to inspect&quot;; registration is a side effect of routing, and synthetic requests pollute the registries under the real line&#39;s id. <code>RouterCore.inspect(id)</code> reads the cache without computing.</li><li><code>route: direct</code>/<code>manual</code> results still register (walls/backbones participate in avoidance and bundling) but never <em>react</em> to other lines.</li><li>Never derive bend/segment counts from raw <code>pts.length</code>; always <code>_compactPolyline(pts).length</code>.</li><li>A channel without <code>discoverable: false</code> is joinable by <em>any</em> nearby <code>auto</code>/<code>smart</code>/<code>grid</code> line, not just ones listing it in <code>route_channels</code>; not a bug, just the automatic-bundling design (see Trunk-and-Branch above).</li></ul><h2 id="known-limitations-deliberately-not-fixed" tabindex="-1">Known Limitations (deliberately not fixed) <a class="header-anchor" href="#known-limitations-deliberately-not-fixed" aria-label="Permalink to &quot;Known Limitations (deliberately not fixed)&quot;">​</a></h2><p>Each was investigated with a concrete attempted fix, not just noticed and left:</p><ul><li><strong><code>trunk_proximity</code> is a hard cutoff</strong> (<code>_discoverTrunkCandidates</code>), not a graduated cost; a line either qualifies to bundle with a nearby trunk or it doesn&#39;t, with a measured cliff right at the threshold. Widening the gate softens the cliff but regresses an already-correct scenario back to its exact pre-fix buggy shape. A real fix needs the proximity check to contribute a graduated cost rather than a boolean gate, a broad enough change to the A* cost landscape to warrant its own regression pass.</li><li><strong><code>_mergeCorridors</code>&#39;s chain-ordering</strong> sorts a line&#39;s candidate trunks by comparing each trunk&#39;s flow-axis coordinate against its own flow span, a fine proxy when every chained trunk shares the line&#39;s dominant travel axis, but incomparable across a mixed horizontal/vertical chain (confirmed via <code>scale-stress.test.js</code>&#39;s <code>manyToOne</code> scenario to occasionally order a farther crossing point before a closer one, forcing a small backtrack). Only reproduces in stress scenarios with several chained mixed-axis trunks. Tracked as a <code>.todo()</code>; a fix needs a genuinely different ordering metric (e.g. predicted crossing-point distance per candidate).</li><li><strong>Arc-vs-arc clearance between two arbitrary (non-bundle-mate) lines</strong> whose corners happen to land near each other, unlike bundle-mates turning the same way, which Matched-Sibling Corner-Arc Clearance (above) solves exactly. A candidate-center-vs-neighbor&#39;s-registered-arc proxy (bounding box, then sample points) gets measurably wrong once the target is a discrete curve. The bundle-mate fix works because a matched sibling&#39;s exact geometry is already known via a shared registry key; two unrelated lines have no such key, so the technique doesn&#39;t generalize without a real &quot;which lines are worth comparing&quot; discovery mechanism of its own.</li><li><strong><code>_buildCrossingCostGrid</code>&#39;s <code>overlapRegions</code>/<code>perpMates</code> formulas are too pervasively load-bearing to edit directly.</strong> Several modification strategies for <code>overlapRegions</code> each regress the full test suite in different combinations; rescoping <code>perpMates</code> regresses both of <code>convergence.test.js</code>&#39;s own fixed-point tests, meaning it&#39;s load-bearing for the discovery loop&#39;s convergence guarantee itself, not just cosmetic shape. Prefer a narrow, additive, upstream-of-the-cost-grid fix (the Corridor-Entry Nudging section is the template) over editing these formulas directly.</li><li><strong><code>_pairwiseCrossCorridorOrder</code>&#39;s cross-line consistency mechanism is deliberately restricted to exactly 2 same-side lines at a corridor</strong> (see Chain-Aware Corridor Lane Consistency above). A same-side group of 3+ has no fix within a pairwise-comparator architecture: independent pairwise resolutions, each potentially via a different seed corridor, have no guarantee of composing into one transitive order. A genuine fix needs a real constraint-satisfaction pass over the whole group at once, not a comparator.</li><li><strong>Chaining through a degenerate channel crossing back toward the line&#39;s own origin</strong> conflicts two of this router&#39;s own invariants: never render a same-axis reversal, and never force a detour when a direct path exists. When a <code>mode: prefer</code> channel&#39;s crossing is degenerate (entry === exit) and the chain&#39;s next channel sits back toward where the line came from, forcing the direct shape reintroduces the reversal those invariants exist to prevent, while blocking it forces an artificial detour instead; the geometry has no third option. Needs its own dedicated design pass, given the direct conflict with already-hardened invariants.</li></ul><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../../cards/msd/routing.html">Line Routing &amp; Channels</a>: user-facing configuration</li><li><a href="./">MSD Pipeline</a>: the rendering pipeline RouterCore plugs into</li><li><code>tests/routing/</code>: the executable specification</li></ul>',75)])])}const p=o(a,[["render",i]]);export{g as __pageData,p as default};
